#!/usr/bin/env node
/**
 * Generate the asset module a compiled single-file binary serves from.
 *
 * The web console normally reads `webui/dist` from disk. A compiled binary has no
 * files next to it, so the same bytes have to travel inside the executable. This
 * script gzips every built frontend file (and the toolbox Dockerfile) into a
 * generated TypeScript module of base64 strings.
 *
 * Base64 in a module, rather than the bundler's own file-embedding feature, keeps
 * the asset layer identical under Node and Bun and keeps `node --check`-style
 * tooling working on the generated file.
 *
 * Usage: node scripts/generate-embedded-assets.mjs
 * Run after `vite build webui`, before `tsc`.
 */

import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const webDir = resolve(scriptDir, "..");
const repoRoot = resolve(webDir, "..", "..");
const distDir = join(webDir, "webui", "dist");
const dockerfilePath = join(repoRoot, "docker", "Dockerfile");
const outFile = join(webDir, "src", "embedded-assets.generated.ts");

if (!existsSync(distDir)) {
	console.error(`前端资源不存在: ${distDir}\n请先执行 npm --prefix packages/web run build:webui`);
	process.exit(1);
}
if (!existsSync(dockerfilePath)) {
	console.error(`工具镜像 Dockerfile 不存在: ${dockerfilePath}`);
	process.exit(1);
}

/** Every regular file under `dir`, as paths relative to `base` with forward slashes. */
function listFiles(dir, base = dir) {
	const found = [];
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const full = join(dir, entry.name);
		if (entry.isDirectory()) {
			found.push(...listFiles(full, base));
		} else if (entry.isFile()) {
			found.push(relative(base, full).split("\\").join("/"));
		}
	}
	return found;
}

function encode(path) {
	return gzipSync(readFileSync(path), { level: 9 }).toString("base64");
}

const files = listFiles(distDir).sort();
if (!files.includes("index.html")) {
	console.error(`${distDir} 里没有 index.html，前端构建不完整`);
	process.exit(1);
}

const webuiEntries = files.map((name) => `\t${JSON.stringify(name)}: "${encode(join(distDir, name))}",`).join("\n");
const dockerfile = encode(dockerfilePath);

// The coding-agent reads its identity (app name, config dir, version) and its docs
// from the package directory next to the code. A single-file binary has neither, so
// carry the small text files and let the binary unpack them at startup.
const codingAgentDir = join(repoRoot, "packages", "coding-agent");
const codingAgentFiles = ["package.json", "README.md", "CHANGELOG.md"].filter((name) =>
	existsSync(join(codingAgentDir, name)),
);
const docsRoot = join(codingAgentDir, "docs");
const docsFiles = existsSync(docsRoot) ? listFiles(docsRoot).filter((name) => name.endsWith(".md")) : [];
const packageEntries = [
	...codingAgentFiles.map((name) => [name, join(codingAgentDir, name)]),
	...docsFiles.map((name) => [`docs/${name}`, join(docsRoot, name)]),
]
	.map(([name, source]) => `\t${JSON.stringify(name)}: "${encode(source)}",`)
	.join("\n");
const packageJson = JSON.parse(readFileSync(join(webDir, "package.json"), "utf8"));
const version = typeof packageJson.version === "string" ? packageJson.version : "0.0.0";

const contents = `// Generated by scripts/generate-embedded-assets.mjs. Do not edit.
//
// ${files.length} frontend file(s) and the toolbox Dockerfile, gzip-compressed and base64-encoded so a
// compiled single-file binary can serve the console and build the image with no files on disk.
// Regenerate with: npm --prefix packages/web run build

/** Frontend files keyed by path relative to webui/dist, gzip-compressed. */
export const EMBEDDED_WEBUI: Record<string, string> = {
${webuiEntries}
};

/** docker/Dockerfile, gzip-compressed, used as the build context when no checkout is present. */
export const EMBEDDED_DOCKERFILE = "${dockerfile}";

/** packages/web/package.json version, so --version works without the file on disk. */
export const EMBEDDED_VERSION = "${version}";

/**
 * coding-agent package files (package.json, README, CHANGELOG, docs/*.md),
 * gzip-compressed, keyed by path relative to that package directory. Unpacked into
 * a temp directory at startup so the identity and doc paths keep resolving.
 */
export const EMBEDDED_CODING_AGENT_FILES: Record<string, string> = {
${packageEntries}
};
`;

writeFileSync(outFile, contents);
const bytes = statSync(outFile).size;
console.log(
	`已生成 ${relative(repoRoot, outFile)}（${files.length} 个前端文件，${packageEntries ? packageEntries.split("\n").length : 0} 个包文件，${(bytes / 1024).toFixed(0)} KB）`,
);
